#ifndef EMBK_PKG_KEY_H
#define EMBK_PKG_KEY_H
/* The trusted package-signing public key (ECDSA P-256). `pkg` verifies every
 * package manifest's signature against THIS key -- trust is in the signature,
 * not the channel (docs/PACKAGING_AND_SDK.md §9.2). The matching private key is
 * a *dev* key at tools/embx/pkgkey_dev.pem (labelled insecure; a real release
 * key would be protected, PK4). Generated by tools/embx/pkgsign.py --emit-key. */
#include <stdint.h>

/* Affine public-key coordinates, 32 big-endian bytes each (P-256). */
static const uint8_t PKG_SIGN_QX[32] = { 0x7b,0xcb,0x29,0x99,0x66,0x64,0xa0,0x2b,0x3a,0x65,0x53,0xd2,0xe1,0xcc,0x85,0x30,0x6c,0xee,0x29,0x2c,0x29,0x09,0x47,0xe2,0x07,0xf4,0x45,0x75,0xa8,0x4b,0xaf,0xd2 };
static const uint8_t PKG_SIGN_QY[32] = { 0x18,0xa9,0x80,0xa9,0xbc,0xfa,0x5d,0xc8,0x60,0x56,0x35,0xac,0xe9,0x98,0x50,0x34,0x56,0x4c,0x51,0x9e,0x5d,0x13,0xa5,0x19,0x8c,0x08,0x39,0x3f,0xe7,0x50,0x67,0xc4 };

#endif /* EMBK_PKG_KEY_H */
